//! NEP-297 events, standard `soulprint` v1.0.0 (A34). This file is the complete event list (A45);
//! `contracts/abi/events.json` holds one sample of each, generated by `abi_fixtures_roundtrip`.
use crate::{Bytes32, Currency, Grant};
use near_sdk::json_types::{U128, U64};
use near_sdk::serde::{Deserialize, Serialize};
use near_sdk::serde_json::{self, json, Value};
use near_sdk::{AccountId, PublicKey};

pub const EVENT_STANDARD: &str = "soulprint";
pub const EVENT_VERSION: &str = "1.0.0";

#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
#[serde(crate = "near_sdk::serde", rename_all = "snake_case")]
pub enum OwnerChangeCause {
    Fund,
    Refund,
    MutualCancel,
    DisputeRefund,
    Transfer,
    TransferCall,
    Sale,
    Revert,
    ExpirePending,
}

#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
#[serde(crate = "near_sdk::serde", rename_all = "snake_case")]
pub enum IssuerClass {
    Client,
    Invited,
}

#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
#[serde(crate = "near_sdk::serde", rename_all = "snake_case")]
pub enum ResolveOutcome {
    Settled,
    Refunded,
}

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq, Eq)]
#[serde(crate = "near_sdk::serde", tag = "event", content = "data", rename_all = "snake_case")]
pub enum SoulprintEvent {
    // --- collection ---
    PieceCreated { piece_id: AccountId, token_id: String, artist: AccountId, mode: String, currency: Currency, terms_hash: Option<Bytes32> },
    KeyProposed { key_id: u16, public_key: PublicKey, activates_at: U64 },
    KeyActivated { key_id: u16 },
    KeyRevoked { key_id: u16 },
    // --- piece: commission ---
    Funded { piece_id: AccountId, payer: AccountId, owner: AccountId, amount: U128, terms_hash: Bytes32 },
    Delivered { piece_id: AccountId, final_file_hash: Bytes32, report_hash: Bytes32, delivered_at: U64 },
    ChangesRequested { piece_id: AccountId, round: u8, new_deadline: U64 },
    MilestoneReleased { piece_id: AccountId, index: u8, amount: U128 },
    Settled { piece_id: AccountId, artist_amount: U128 },
    Refunded { piece_id: AccountId, to: AccountId, amount: U128 },
    Cancelled { piece_id: AccountId },
    DeadlineExtended { piece_id: AccountId, new_deadline: U64 },
    ReopenedStandalone { piece_id: AccountId },
    // --- piece: dispute ---
    Rejected { piece_id: AccountId, by: AccountId },
    BondPosted { piece_id: AccountId, by: AccountId, amount: U128 },
    BondPaid { piece_id: AccountId, to: AccountId, amount: U128 },
    SplitProposed { piece_id: AccountId, by: AccountId, artist_bps: u16, nonce: u32 },
    Resolved { piece_id: AccountId, by: Option<AccountId>, artist_bps: u16, artist_amount: U128, owner_amount: U128, outcome: ResolveOutcome },
    // --- piece: money ---
    Income { piece_id: AccountId, payer: AccountId, amount: U128 },
    Withdraw { piece_id: AccountId, owner: AccountId, amount: U128 },
    Claim { piece_id: AccountId, creditor: AccountId, recipient: AccountId, amount: U128 },
    ClaimRestored { piece_id: AccountId, creditor: AccountId, amount: U128 },
    // --- piece: resale / ownership ---
    Listed { piece_id: AccountId, seller: AccountId, price: U128, nonce: U64, reserved_for: Option<AccountId> },
    Delisted { piece_id: AccountId, nonce: U64 },
    Sold { piece_id: AccountId, seller: AccountId, buyer: AccountId, price: U128, royalty: U128, nonce: U64 },
    OwnerChanged { piece_id: AccountId, old_owner: AccountId, new_owner: AccountId, seq: U64, cause: OwnerChangeCause },
    TransferPending { piece_id: AccountId, from: AccountId, to: AccountId, seq: U64, expires_at: U64 },
    TransferReverted { piece_id: AccountId, to: AccountId, seq: U64 },
    // --- piece: proof ---
    Anchored { piece_id: AccountId, key: PublicKey, head: Bytes32, count: u32 },
    CaptureKeyAdded { piece_id: AccountId, key: PublicKey },
    ChallengerInvited { piece_id: AccountId, account: AccountId },
    ChallengeIssued { piece_id: AccountId, challenge_id: u32, issuer: AccountId, issuer_class: IssuerClass, nonce_hash: Bytes32 },
    ChallengeAcked { piece_id: AccountId, challenge_id: u32, acked_at: U64 },
    Attested { piece_id: AccountId, key_id: u16, evidence_level: u8, report_hash: Bytes32, issued_at: U64 },
    AddendumProposed { piece_id: AccountId, grant: Grant, text_hash: Bytes32 },
    AddendumAccepted { piece_id: AccountId, grant: Grant, text_hash: Bytes32 },
}

impl SoulprintEvent {
    pub fn name(&self) -> String {
        let v = serde_json::to_value(self).expect("event json");
        v["event"].as_str().expect("event name").to_string()
    }

    /// `EVENT_JSON:{"standard":"soulprint","version":"1.0.0","event":..,"data":[{..}]}`
    pub fn to_log(&self) -> String {
        let v = serde_json::to_value(self).expect("event json");
        let data = v.get("data").cloned().unwrap_or(Value::Null);
        let data = if data.is_null() { json!([]) } else { json!([data]) };
        let out = json!({ "standard": EVENT_STANDARD, "version": EVENT_VERSION, "event": v["event"], "data": data });
        format!("EVENT_JSON:{out}")
    }

    pub fn emit(&self) {
        near_sdk::env::log_str(&self.to_log());
    }

    pub fn from_nep297(v: &Value) -> Result<Self, String> {
        if v["standard"] != EVENT_STANDARD || v["version"] != EVENT_VERSION {
            return Err("wrong standard/version".into());
        }
        let data = v["data"].as_array().and_then(|a| a.first().cloned());
        let mut obj = json!({ "event": v["event"] });
        if let Some(d) = data {
            obj["data"] = d;
        }
        serde_json::from_value(obj).map_err(|e| e.to_string())
    }

    /// One sample per variant, for ABI fixtures consumed by Plans 2 and 3.
    pub fn samples() -> Vec<Self> {
        use SoulprintEvent::*;
        let p: AccountId = "p7.soulprint-v1.x.testnet".parse().unwrap();
        let a: AccountId = "artist.testnet".parse().unwrap();
        let c: AccountId = "client.testnet".parse().unwrap();
        let b: AccountId = "buyer.testnet".parse().unwrap();
        let pk: PublicKey = "ed25519:6E8sCci9badyRkXb3JoRpBj5p8C6Tw41ELDZoiihKEtp".parse().unwrap();
        let h = Bytes32([1; 32]);
        let amt = U128(1_000_000);
        let t = U64(1_800_000_000_000_000_000);
        let grant = Grant { kind: crate::GrantType::CommercialNonExclusive, attribution: true, transferable: true };
        vec![
            PieceCreated { piece_id: p.clone(), token_id: "7".into(), artist: a.clone(), mode: "commission".into(), currency: Currency::Ft("usdc.testnet".parse().unwrap()), terms_hash: Some(h) },
            KeyProposed { key_id: 1, public_key: pk.clone(), activates_at: t },
            KeyActivated { key_id: 1 },
            KeyRevoked { key_id: 1 },
            Funded { piece_id: p.clone(), payer: c.clone(), owner: c.clone(), amount: amt, terms_hash: h },
            Delivered { piece_id: p.clone(), final_file_hash: h, report_hash: h, delivered_at: t },
            ChangesRequested { piece_id: p.clone(), round: 1, new_deadline: t },
            MilestoneReleased { piece_id: p.clone(), index: 0, amount: amt },
            Settled { piece_id: p.clone(), artist_amount: amt },
            Refunded { piece_id: p.clone(), to: c.clone(), amount: amt },
            Cancelled { piece_id: p.clone() },
            DeadlineExtended { piece_id: p.clone(), new_deadline: t },
            ReopenedStandalone { piece_id: p.clone() },
            Rejected { piece_id: p.clone(), by: c.clone() },
            BondPosted { piece_id: p.clone(), by: c.clone(), amount: amt },
            BondPaid { piece_id: p.clone(), to: a.clone(), amount: amt },
            SplitProposed { piece_id: p.clone(), by: a.clone(), artist_bps: 6000, nonce: 1 },
            Resolved { piece_id: p.clone(), by: Some("arb.testnet".parse().unwrap()), artist_bps: 6000, artist_amount: amt, owner_amount: amt, outcome: ResolveOutcome::Settled },
            Income { piece_id: p.clone(), payer: "shop.testnet".parse().unwrap(), amount: amt },
            Withdraw { piece_id: p.clone(), owner: c.clone(), amount: amt },
            Claim { piece_id: p.clone(), creditor: a.clone(), recipient: a.clone(), amount: amt },
            ClaimRestored { piece_id: p.clone(), creditor: a.clone(), amount: amt },
            Listed { piece_id: p.clone(), seller: c.clone(), price: amt, nonce: U64(1), reserved_for: None },
            Delisted { piece_id: p.clone(), nonce: U64(1) },
            Sold { piece_id: p.clone(), seller: c.clone(), buyer: b.clone(), price: amt, royalty: U128(50_000), nonce: U64(1) },
            OwnerChanged { piece_id: p.clone(), old_owner: c.clone(), new_owner: b.clone(), seq: U64(3), cause: OwnerChangeCause::Sale },
            TransferPending { piece_id: p.clone(), from: c.clone(), to: b.clone(), seq: U64(4), expires_at: t },
            TransferReverted { piece_id: p.clone(), to: c.clone(), seq: U64(5) },
            Anchored { piece_id: p.clone(), key: pk.clone(), head: h, count: 12 },
            CaptureKeyAdded { piece_id: p.clone(), key: pk },
            ChallengerInvited { piece_id: p.clone(), account: "judge.testnet".parse().unwrap() },
            ChallengeIssued { piece_id: p.clone(), challenge_id: 0, issuer: c.clone(), issuer_class: IssuerClass::Client, nonce_hash: h },
            ChallengeAcked { piece_id: p.clone(), challenge_id: 0, acked_at: t },
            Attested { piece_id: p.clone(), key_id: 1, evidence_level: 3, report_hash: h, issued_at: t },
            AddendumProposed { piece_id: p.clone(), grant, text_hash: h },
            AddendumAccepted { piece_id: p, grant, text_hash: h },
        ]
    }
}
